type Risk     = {volatility:number;sharpe:number;max_drawdown:number;win_rate:number};

function PriceChart({data,width,height}:{data:ChartPt[];width:number;height:number}){
  const ref=useRef<HTMLCanvasElement>(null);
  useEffect(()=>{
    const canvas=ref.current;if(!canvas||!data.length)return;
    const ctx=canvas.getContext("2d");if(!ctx)return;
    const dpr=window.devicePixelRatio||1;
    canvas.width=width*dpr;canvas.height=height*dpr;ctx.scale(dpr,dpr);
    const pad={top:20,right:20,bottom:30,left:55};
    const W=width-pad.left-pad.right,H=height-pad.top-pad.bottom;
    ctx.clearRect(0,0,width,height);
    const all=data.flatMap(d=>[d.price,d.ma50,d.pred].filter(v=>v!==null)) as number[];
    if(!all.length)return;
    const minV=Math.min(...all)-5,maxV=Math.max(...all)+5;
    const toY=(v:number)=>pad.top+H-((v-minV)/(maxV-minV))*H;
    const toX=(i:number)=>pad.left+(i/(data.length-1))*W;
    ctx.strokeStyle="#21262d";ctx.lineWidth=0.5;
    for(let i=0;i<=4;i++){
      const y=pad.top+(H/4)*i;
      ctx.beginPath();ctx.moveTo(pad.left,y);ctx.lineTo(pad.left+W,y);ctx.stroke();
      ctx.fillStyle="#8b949e";ctx.font="10px system-ui";ctx.textAlign="right";
      ctx.fillText("$"+Math.round(maxV-((maxV-minV)/4)*i),pad.left-6,y+4);
    }
    ctx.fillStyle="#8b949e";ctx.font="10px system-ui";ctx.textAlign="center";
    const step=Math.ceil(data.length/8);
    data.forEach((d,i)=>{if(i%step===0)ctx.fillText(d.date,toX(i),height-4);});
    ctx.strokeStyle=C.hold;ctx.lineWidth=1.5;ctx.globalAlpha=0.7;ctx.beginPath();
    let f=true;data.forEach((d,i)=>{if(d.ma50===null)return;f?(ctx.moveTo(toX(i),toY(d.ma50)),f=false):ctx.lineTo(toX(i),toY(d.ma50));});
    ctx.stroke();ctx.globalAlpha=1;
    const pts=data.map((d,i)=>d.price!==null?{x:toX(i),y:toY(d.price)}:null).filter(Boolean) as {x:number;y:number}[];
    if(pts.length){
      const g=ctx.createLinearGradient(0,pad.top,0,pad.top+H);
      g.addColorStop(0,"rgba(0,212,170,0.25)");g.addColorStop(1,"rgba(0,212,170,0)");
      ctx.beginPath();ctx.moveTo(pts[0].x,pad.top+H);
      pts.forEach(p=>ctx.lineTo(p.x,p.y));
      ctx.lineTo(pts[pts.length-1].x,pad.top+H);ctx.closePath();ctx.fillStyle=g;ctx.fill();
      ctx.strokeStyle=C.accent;ctx.lineWidth=2.5;ctx.beginPath();
      pts.forEach((p,i)=>i===0?ctx.moveTo(p.x,p.y):ctx.lineTo(p.x,p.y));ctx.stroke();
    }
    ctx.strokeStyle=C.purple;ctx.lineWidth=2;ctx.setLineDash([6,3]);ctx.beginPath();
    let fp=true;data.forEach((d,i)=>{if(d.pred===null)return;fp?(ctx.moveTo(toX(i),toY(d.pred)),fp=false):ctx.lineTo(toX(i),toY(d.pred));});
    ctx.stroke();ctx.setLineDash([]);
  },[data,width,height]);
  return <canvas ref={ref} style={{width,height,display:"block"}}/>;
}

function MiniChart({data}:{data:PortHist[]}){
  const ref=useRef<HTMLCanvasElement>(null);
  useEffect(()=>{
    const canvas=ref.current;if(!canvas||!data.length)return;
    const ctx=canvas.getContext("2d");if(!ctx)return;
    const W=canvas.offsetWidth||300,H=80,dpr=window.devicePixelRatio||1;
    canvas.width=W*dpr;canvas.height=H*dpr;ctx.scale(dpr,dpr);ctx.clearRect(0,0,W,H);
    const vals=data.map(d=>d.v),min=Math.min(...vals)-500,max=Math.max(...vals)+500;
    const tx=(i:number)=>(i/(data.length-1))*W;
    const ty=(v:number)=>H-10-((v-min)/(max-min))*(H-20);
    const g=ctx.createLinearGradient(0,0,0,H);
    g.addColorStop(0,"rgba(0,212,170,0.25)");g.addColorStop(1,"rgba(0,212,170,0)");
    ctx.beginPath();ctx.moveTo(tx(0),H);
    data.forEach((d,i)=>ctx.lineTo(tx(i),ty(d.v)));
    ctx.lineTo(tx(data.length-1),H);ctx.fillStyle=g;ctx.fill();
    ctx.strokeStyle=C.accent;ctx.lineWidth=2;ctx.beginPath();
    data.forEach((d,i)=>i===0?ctx.moveTo(tx(i),ty(d.v)):ctx.lineTo(tx(i),ty(d.v)));ctx.stroke();
    ctx.fillStyle="#8b949e";ctx.font="9px system-ui";ctx.textAlign="center";
    data.forEach((d,i)=>ctx.fillText(d.m,tx(i),H-1));
  },[data]);
  return <canvas ref={ref} style={{width:"100%",height:80,display:"block"}}/>;
}

function Badge({type}:{type:string}){
  const map:Record<string,[string,string]>={BUY:["rgba(16,185,129,0.15)","#10b981"],SELL:["rgba(239,68,68,0.15)","#ef4444"],HOLD:["rgba(245,158,11,0.15)","#f59e0b"],positive:["rgba(16,185,129,0.1)","#10b981"],negative:["rgba(239,68,68,0.1)","#ef4444"],neutral:["rgba(139,148,158,0.12)","#8b949e"]};
  const [bg,color]=map[type]||map.neutral;
  return <span style={{background:bg,color,border:`1px solid ${color}44`,padding:"2px 8px",borderRadius:4,fontSize:10,fontWeight:700,flexShrink:0}}>{type.toUpperCase()}</span>;
}

function Bar({pct,color,h=3}:{pct:number;color:string;h?:number}){
  return <div style={{height:h,background:C.border,borderRadius:2,marginTop:4}}><div style={{width:`${Math.min(pct,100)}%`,height:"100%",background:color,borderRadius:2,transition:"width 0.6s ease"}}/></div>;
}

function Spin(){return <div style={{display:"flex",alignItems:"center",justifyContent:"center",height:80,color:C.muted,fontSize:12}}>Loading...</div>;}

